type Style = { [key: string]: string | Style };

function merge(...styles: (Style | undefined)[]): Style {
  const out: Style = {};
  for (const style of styles)
    for (const [k, v] of Object.entries(style ?? {}))
      out[k] =
        typeof v === 'object' && typeof out[k] === 'object'
          ? merge(out[k] as Style, v)
          : v;
  return out;
}

/** The complete style for one set of props, for `sx` or `styleOverrides.root`. */
export function solarTabsStyle(props: SolarTabsProps = {}): Style {
  const p: Record<string, unknown> = { ...solarTabsDefaults };
  for (const [k, v] of Object.entries(props)) if (v !== undefined) p[k] = v;
  const key = `default`;
  const s = solarTabsStyles as unknown as {
    reset: Style;
    root: Style;
    sizes: Record<string, Style>;
    appearances: Record<string, Style>;
    combined: Record<string, Record<string, Style>>;
  };
  const size = p.size as string;
  return merge(
    s.reset,
    s.root,
    s.sizes[size],
    s.appearances[key],
    s.combined[size]?.[key],
  );
}

